275: /// `Display` implement for `SourceLocation`.
276: ///
277: /// This is used to format source locations for individual checks. But source
278: /// locations may be printed in a different way in other places (e.g., in the
279: /// "Failed Checks" summary at the end).
280: ///
281: /// Source locations formatted this way will look like:
282: /// `<file>:<line>:<column> in function <function>`
283: /// if all attributes were specified. Otherwise, we:
284: ///  * Omit `in function <function>` if the function isn't specified.
285: ///  * Use `Unknown file` instead of `<file>:<line>:<column>` if the file isn't
286: ///    specified.
287: ///  * Lines and columns are only formatted if they were specified and preceding
288: ///    attribute was formatted.
289: impl std::fmt::Display for SourceLocation {
290:     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
291:         if let Some(file) = self.file.clone() {
292:             let file_path = filepath(file);
293:             write!(f, "{file_path}")?;
294:             if let Some(line) = self.line.clone() {
295:                 write!(f, ":{line}")?;
296:                 if let Some(column) = self.column.clone() {
297:                     write!(f, ":{column}")?;
298:                 }
299:             }
300:         } else {
301:             write!(f, "Unknown file")?;
302:         }
303:         if let Some(function) = self.function.clone() {
304:             let demangled_function = demangle(&function);
305:             write!(f, " in function {demangled_function:#}")?;
306:         }
307:         Ok(())
308:     }
309: }
