274: pub fn format_result(
275:     properties: &Vec<Property>,
276:     status: VerificationStatus,
277:     should_panic: bool,
278:     failed_properties: FailedProperties,
279:     show_checks: bool,
280: ) -> String {
281:     let mut result_str = String::new();
282:     let mut number_checks_failed = 0;
283:     let mut number_checks_unreachable = 0;
284:     let mut number_checks_undetermined = 0;
285:     let mut failed_tests: Vec<&Property> = vec![];
286: 
287:     // cover checks
288:     let mut number_covers_satisfied = 0;
289:     let mut number_covers_undetermined = 0;
290:     let mut number_covers_unreachable = 0;
291:     let mut number_covers_unsatisfiable = 0;
292: 
293:     if show_checks {
294:         result_str.push_str("\nRESULTS:\n");
295:     }
296: 
297:     for (index, prop) in (1..).zip(properties) {
298:         let name = prop.property_name();
299:         let status = &prop.status;
300:         let description = &prop.description;
301:         let location = &prop.source_location;
302: 
303:         match status {
304:             CheckStatus::Failure => {
305:                 number_checks_failed += 1;
306:                 failed_tests.push(prop);
307:             }
308:             CheckStatus::Undetermined => {
309:                 if prop.is_cover_property() {
310:                     number_covers_undetermined += 1;
311:                 } else {
312:                     number_checks_undetermined += 1;
313:                 }
314:             }
315:             CheckStatus::Unreachable => {
316:                 if prop.is_cover_property() {
317:                     number_covers_unreachable += 1;
318:                 } else {
319:                     number_checks_unreachable += 1;
320:                 }
321:             }
322:             CheckStatus::Satisfied => {
323:                 assert!(prop.is_cover_property());
324:                 number_covers_satisfied += 1;
325:             }
326:             CheckStatus::Unsatisfiable => {
327:                 assert!(prop.is_cover_property());
328:                 number_covers_unsatisfiable += 1;
329:             }
330:             _ => (),
331:         }
332: 
333:         if show_checks {
334:             let check_id = format!("Check {index}: {name}\n");
335:             let status_msg = format!("\t - Status: {status}\n");
336:             let description_msg = format!("\t - Description: \"{description}\"\n");
337: 
338:             result_str.push_str(&check_id);
339:             result_str.push_str(&status_msg);
340:             result_str.push_str(&description_msg);
341: 
342:             if !location.is_missing() {
343:                 let location_msg = format!("\t - Location: {location}\n");
344:                 result_str.push_str(&location_msg);
345:             }
346:             result_str.push('\n');
347:         }

